    public static let cuesFr: [String: [String]] = ["Chest": ["Rentre les omoplates et garde-les collées au banc.", "Descends la charge sous contrôle jusqu'à sentir l'étirement des pectoraux.", "Pousse vers le haut sans ouvrir les coudes au-delà de 75° environ."], "Shoulders": ["Garde les côtes basses — ne creuse pas le dos pour pousser.", "Sur les élévations, guide avec les coudes et arrête-toi à hauteur d'épaules.", "Contrôle la descente : le deltoïde travaille le plus à la phase négative."], "Biceps": ["Garde les coudes collés au corps.", "Ne balance pas le buste ; descends en 2–3 secondes.", "Serre fort en haut et étends complètement le bras en bas."], "Triceps": ["Coudes fixes — seuls les avant-bras bougent.", "Atteins l'extension complète à chaque répétition.", "Ne laisse pas les coudes s'écarter quand la fatigue arrive."], "Lats": ["Démarre en ramenant les coudes vers les hanches, pas en tirant avec les mains.", "Poitrine haute, ne te penche pas trop en arrière.", "Étire complètement en haut, marque une pause en bas."], "Lower back": ["Gaine les abdos et garde le dos neutre jusqu'au verrouillage.", "Pousse le sol et termine en poussant les hanches vers l'avant.", "Reprends ta respiration et ta posture entre les répétitions lourdes."], "Traps": ["Monte les épaules tout droit — ne les roule pas.", "Marque une seconde complète en haut.", "Descends les épaules sur toute l'amplitude en bas."], "Quads": ["Garde les genoux alignés sur les orteils.", "Descends sous contrôle au moins à la parallèle.", "Pousse avec le milieu du pied, pas les orteils."], "Hamstrings": ["Charnière des hanches, garde juste une légère flexion des genoux.", "Cherche l'étirement profond en bas avant de remonter.", "Garde la charge proche des jambes pendant tout le mouvement."], "Glutes": ["Verrouille les hanches complètement et serre fort en haut.", "Menton rentré, côtes basses.", "Pousse avec les talons pour garder la tension sur les fessiers."], "Abductors": ["Bouge lentement et garde le buste droit.", "Marque une brève pause contre la résistance au point le plus large."], "Adductors": ["Bouge lentement et sous contrôle.", "Marque une brève pause contre la résistance au point le plus serré."], "Calves": ["Marque une seconde complète en haut de chaque répétition.", "Descends lentement sur toute l'amplitude pour un étirement profond.", "Garde les genoux tendus pour cibler les mollets."], "Abs": ["Expire et gaine-toi en remontant.", "Bouge avec contrôle — pas d'élan.", "Garde le bas du dos collé au sol quand indiqué."], "Forearms": ["Seuls les poignets bougent ; les coudes restent fixes.", "Tempo lent et répétitions hautes."]]
