    public static let archStepsFr: [String: [String]] = ["bench": ["Allonge-toi sur le banc, yeux sous la barre, pieds bien ancrés au sol.", "Prends la barre un peu plus large que les épaules et décroche-la.", "Descends la barre au milieu des pectoraux, coudes à environ 75°.", "Pousse vers le haut et légèrement en arrière jusqu'à l'extension complète."], "incline_bench": ["Incline le banc à 30–45° et cale les omoplates en arrière.", "Décroche la charge au-dessus du haut des pectoraux.", "Descends vers la ligne des clavicules, coudes rentrés.", "Pousse en revenant à la position de départ."], "decline_bench": ["Cale tes jambes au bout du banc décliné et allonge-toi.", "Décroche la barre avec une prise largeur d'épaules.", "Descends la barre vers le bas des pectoraux, coudes rentrés.", "Pousse puissamment jusqu'à l'extension."], "fly": ["Mets-toi en place avec une légère flexion des coudes, gardée fixe toute la série.", "Ouvre les bras en grand arc jusqu'à sentir l'étirement des pectoraux.", "Referme les bras comme si tu enlaçais un tonneau.", "Marque une pause à la contraction maximale avant la répétition suivante."], "pushup": ["Place les mains un peu plus large que les épaules, corps aligné.", "Gaine les abdos et serre les fessiers.", "Descends jusqu'à ce que la poitrine frôle le sol, coudes à environ 45°.", "Pousse le sol loin de toi jusqu'à l'extension complète."], "ohp": ["Debout, pieds largeur d'épaules, barre posée sur les deltoïdes avant.", "Gaine le gainage et serre les fessiers pour bloquer le bassin.", "Pousse la barre verticalement en dégageant la tête en arrière.", "Verrouille au-dessus de la tête, barre au-dessus du milieu du pied, puis redescends sous contrôle."], "lateral_raise": ["Debout bien droit, poids le long du corps, coudes légèrement fléchis.", "Guide avec les coudes et monte les bras sur les côtés.", "Arrête-toi à hauteur d'épaules — pas plus haut.", "Descends lentement sur 2–3 secondes."], "front_raise": ["Debout, poids devant les cuisses.", 